from hbexpense.models import Conflict, NotFound


class ClaimRepository:
    def __init__(self):
        self._claims = {}
        self._seq = 0

    def next_id(self, month):
        self._seq += 1
        return f"EX-{month.replace('-', '')[2:]}{self._seq:03d}"

    def add(self, claim):
        if claim.claim_id in self._claims:
            raise Conflict(f"duplicate claim {claim.claim_id}")
        self._claims[claim.claim_id] = claim
        return claim

    def get(self, claim_id):
        try:
            return self._claims[claim_id]
        except KeyError:
            raise NotFound(f"claim {claim_id} not found") from None

    def by_status(self, status):
        return [c for c in self._claims.values() if c.status == status]

    def in_month(self, month):
        return [c for c in self._claims.values() if c.spent_on.startswith(month + "-")]

    def by_ref(self, ref):
        return self._claims.get(ref)

    def all(self):
        return list(self._claims.values())
"""Tiny TTL cache for computed reports."""
import time


class TTLCache:
    def __init__(self, ttl, clock=None):
        self.ttl = ttl
        self._clock = clock or time.monotonic
        self._data = {}

    def get(self, key):
        item = self._data.get(key)
        if item is None:
            return None
        stored_at, value = item
        if self._clock() - stored_at > self.ttl:
            del self._data[key]
            return None
        return value

    def put(self, key, value):
        self._data[key] = (self._clock(), value)

    def invalidate(self, prefix=""):
        for key in [k for k in self._data if str(k).startswith(prefix)]:
            del self._data[key]

    def clear(self):
        self._data.clear()
