"""Whether posted claims are booked in the ledger, judged from period lists only.

Per-entry `show` is never used on the service path (EXP-412): a receipt counts
as booked when it appears in the ledger's list for the claim's month.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of

BOOKED = "booked"
NOT_BOOKED = "not_booked"


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def statuses(self, claims):
        """Map claim id -> ledger_status; one period list call per month involved."""
        result = {c.claim_id: None for c in claims}
        receipts_by_month = {}
        for claim in claims:
